{"Table":"mh_tb_questions","Create Table":"CREATE TABLE `mh_tb_questions` (\n  `id` varchar(36) NOT NULL,\n  `user` varchar(255) NOT NULL,\n  `difficulty` varchar(255) NOT NULL,\n  `question` varchar(255) NOT NULL,\n  `correct_answer` double NOT NULL,\n  `answer` double NOT NULL,\n  `current_score` double NOT NULL,\n  `answering_time` double NOT NULL,\n  `is_corret` tinyint(1) NOT NULL,\n  `has_multiplication` tinyint(1) NOT NULL,\n  `has_division` tinyint(1) NOT NULL,\n  `steps` int(11) NOT NULL DEFAULT 1,\n  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),\n  `updated_at` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),\n  PRIMARY KEY (`id`),\n  KEY `FK_question_user` (`user`),\n  CONSTRAINT `FK_question_user` FOREIGN KEY (`user`) REFERENCES `mh_tb_user` (`id`) ON DELETE CASCADE ON UPDATE CASCADE\n) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci","json":{"name":"mh_tb_questions.sql","path":"files/sql/rod/mh_tb_questions.sql","sha":"a8f017bebb7de523fa0a66270be63d2a7f561d41","size":1361852,"url":"https://api.github.com/repos/rodcordeiro/shares/contents/files/sql/rod/mh_tb_questions.sql?ref=master","html_url":"https://github.com/rodcordeiro/shares/blob/master/files/sql/rod/mh_tb_questions.sql","git_url":"https://api.github.com/repos/rodcordeiro/shares/git/blobs/a8f017bebb7de523fa0a66270be63d2a7f561d41","download_url":"https://raw.githubusercontent.com/rodcordeiro/shares/master/files/sql/rod/mh_tb_questions.sql","type":"file","content":"","encoding":"none","_links":{"self":"https://api.github.com/repos/rodcordeiro/shares/contents/files/sql/rod/mh_tb_questions.sql?ref=master","git":"https://api.github.com/repos/rodcordeiro/shares/git/blobs/a8f017bebb7de523fa0a66270be63d2a7f561d41","html":"https://github.com/rodcordeiro/shares/blob/master/files/sql/rod/mh_tb_questions.sql"}},"pairedItem":{"item":33},"index":33}